import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"10、【履】 兑下乾上","description":"周易口诀义 - 10、【履】 兑下乾上","frontmatter":{"title":"10、【履】 兑下乾上","description":"周易口诀义 - 10、【履】 兑下乾上"},"headers":[],"relativePath":"zh/classics/koujueyi/012.md","filePath":"zh/classics/koujueyi/012.md"}'),r={name:"zh/classics/koujueyi/012.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_10、【履】-兑下乾上" tabindex="-1">10、【履】 兑下乾上 <a class="header-anchor" href="#_10、【履】-兑下乾上" aria-label="Permalink to “10、【履】 兑下乾上”">​</a></h1><p>彖曰：履，柔履刚也。说而应乎乾，是以「履虎尾，不咥人，亨」。刚中正，履帝位而不疚，光明也。</p><p>象曰：上天下泽，履。君子以辨上下，定民志。</p><p>初九：素履往，无咎。</p><p>象曰：素履之往，独行愿也。</p><p>九二：履道坦坦，幽人贞吉。</p><p>象曰：「幽人贞吉」，中不自乱也。</p><p>六三：眇能视，跛能履，履虎尾，咥人，凶。武人为于大君。</p><p>象曰：「眇能视」，不足以有明也。「跛能履」，不足以与行也。咥人之凶，位不当也。「武人为于大君」，志刚也。</p><p>九四：履虎尾，诉诉，终吉。象曰：「诉诉终吉」，志行也。</p><p>九五：夬履，贞厉。</p><p>象曰：「夬履贞厉」，位正当也。</p><p>上九：视履考祥，其旋元吉。</p><p>象曰：元吉在上，大有庆也。</p><p>解读</p><p>「履虎尾，不咥人，亨」者，履，礼也，践也。故先儒云：「统之于心曰体，践而行之曰履。」夫礼尚卑谦，今六三以柔乘刚，违谦越礼，如履践虎尾，言其危惧之甚也。「不咥人亨」者，咥，啮也；虽复履践虎尾，以其悦奉于刚正之德，所以不被咥啮而得亨通也。</p><p>象曰：「上天下泽，履，君子以辨上下，定民志」者，天尊泽卑，各得其序，故曰「履，礼之象也」。君子以分辨上下，君臣有礼，正定人民志意，使尊卑有别也。</p><p>「初九，素履，往无咎」者，礼贵俭约，今初九处履之初，不尚华饰，以质素为用，既行其礼以素，可以往而「无咎」矣。</p><p>「九二，履道坦坦，幽人贞吉」者，坦坦，平易之貌。九二阳居阴而用卑巽，往之于应，途路平坦，无所险厄，故曰「履道坦坦」也。在内履中，谦巽以行，不以处内为屈，居外为荣，是幽隐之人，而不失贞正之道，故曰「幽人贞吉」也。</p><p>「六三，眇能视，跛能履，履虎尾，咥人凶，武人为于大君」者，以阴居阳，不行谦巽之道，犹如眇目之人，所视不明也，跛足之人，所行不能远也。既无谦巽之行，则为物害，犹如履践虎尾，必见咥啮，所以「凶」也。以微劣之躯，而欲行其刚武，为于大君，是凶顽之甚，故曰「武人为于大君」也。</p><p>「九四：履虎尾，诉诉，终吉」者，子夏传：「诉诉，恐惧之貌也」。九四逼近至尊，心之忧惧，若蹈虎尾而诉诉恐惧，故书云「若蹈虎尾，涉于春冰」是也。以阳居阴，用之谦巽，上奉于君，故「终吉」也。</p><p>「九五：夬履，贞厉」者，夬，决也；为履之主，裁之以义，正之以礼，故以刚决贞，故曰「夬履，贞厉」也。然以阳居尊，满之道矣。礼尚谦虚，而以盈满为用，是危厉者也。</p><p>上九：视履考祥，其旋元吉者，考，是察也；祥，谓祯祥也；旋，反也。上九处履之极，能察祸福祯祥也。又能视其所履践之德行，不为骄怠，而能旋反行礼，以应尊卑，施惠向下，故获「大吉」也。</p>',23)])])}const u=e(r,[["render",i]]);export{h as __pageData,u as default};
